def solve_two_degrees():
    max_s = 0
    for nD in range(1, 11):
        nd_val = 11 - nD
        for D in range(11):
            for d in range(11):
                if D == d:
                    continue

                # e_Dd is the number of edges between the two sets.
                # Constraints:
                # 1. e_Dd <= nD * nd_val
                # 2. e_Dd <= nD * D
                # 3. e_Dd <= nd_val * d
                # 4. nD*D - e_Dd is even and 0 <= nD*D - e_Dd <= nD*(nD-1)
                # 5. nd_val*d - e_Dd is even and 0 <= nd_val*d - e_Dd <= nd_val*(nd_val-1)

                lower_bound = max(0, nD*(D - nD + 1), nd_val*(d - nd_val + 1))
                upper_bound = min(nD*D, nd_val*d, nD*nd_val)

                for e_Dd in range(lower_bound, upper_bound + 1):
                    if (nD*D - e_Dd) % 2 == 0 and (nd_val*d - e_Dd) % 2 == 0:
                        max_s = max(max_s, e_Dd * abs(D - d))
    return max_s

